type OrderStatus string

const (
	OrderStatusDraft           OrderStatus = "draft"
	OrderStatusNew             OrderStatus = "new"
	OrderStatusConfirmed       OrderStatus = "confirmed"
	OrderStatusCancelRequested OrderStatus = "cancel_requested"
	OrderStatusCancelled       OrderStatus = "cancelled"
	OrderStatusDelivered       OrderStatus = "delivered"
	OrderStatusReturned        OrderStatus = "returned"
)

// AllValues returns all OrderStatus values.
func (OrderStatus) AllValues() []OrderStatus {
	return []OrderStatus{
		OrderStatusDraft,
		OrderStatusNew,
		OrderStatusConfirmed,
		OrderStatusCancelRequested,
		OrderStatusCancelled,
		OrderStatusDelivered,
		OrderStatusReturned,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s OrderStatus) MarshalText() ([]byte, error) {
	switch s {
	case OrderStatusDraft:
		return []byte(s), nil
	case OrderStatusNew:
		return []byte(s), nil
	case OrderStatusConfirmed:
		return []byte(s), nil
	case OrderStatusCancelRequested:
		return []byte(s), nil
	case OrderStatusCancelled:
		return []byte(s), nil
	case OrderStatusDelivered:
		return []byte(s), nil
	case OrderStatusReturned:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *OrderStatus) UnmarshalText(data []byte) error {
	switch OrderStatus(data) {
	case OrderStatusDraft:
		*s = OrderStatusDraft
		return nil
	case OrderStatusNew:
		*s = OrderStatusNew
		return nil
	case OrderStatusConfirmed:
		*s = OrderStatusConfirmed
		return nil
	case OrderStatusCancelRequested:
		*s = OrderStatusCancelRequested
		return nil
	case OrderStatusCancelled:
		*s = OrderStatusCancelled
		return nil
	case OrderStatusDelivered:
		*s = OrderStatusDelivered
		return nil
	case OrderStatusReturned:
		*s = OrderStatusReturned
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

